scwin.listSync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_dep_usr",
        action : "/depusr.do",
        ref : "",
        target : "MxDataSet_dep_usr=body.content",
        // TODO Stage2: submitdone 핸들러 미정의 (sbm_MxDataSet_dep_usr 서브미션 노드/데이터셋 이 화면에 없음 — 데드 호출 가능성)
        submitDoneHandler : scwin.sbm_MxDataSet_dep_usr_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);

    scwin.listSyncHeader();
    scwin.listSyncPart();
    scwin.listSyncTeam();
};

