scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    let cCnt = 0;
    for (let i = 1; i <= sval.getRowCount(); i++) { // TODO Stage2: 0-based 검토
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

scwin.undo = function(sval) {
    sval.undoall();
};

scwin.gform_onload = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_dep_header",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_header=body.content",
        submitDoneHandler : scwin.MxDataSet_dep_header_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_MxDataSet_dep_part",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_part=body.content",
        submitDoneHandler : scwin.MxDataSet_dep_part_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


    const sbmOptions3 = {
        id : "sbm_MxDataSet_dep_team",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_team=body.content",
        submitDoneHandler : scwin.MxDataSet_dep_team_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);


    const sbmOptions4 = {
        id : "sbm_MxDataSet_chrgteam",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
